#!/bin/bash
# Test optimized cleanup - removes all sbtest tables regardless of template

# Connection info
DB_HOST="192.168.134.129"
DB_PORT="3357"
DB_USER="root"
DB_PASS="root@123"
DB_NAME="sbtest"

echo "========================================"
echo "Testing Optimized Cleanup"
echo "========================================"
echo ""

# Step 1: Create multiple test tables \(simulating different template runs\)
echo "Step 1: Creating test tables \(sbtest1-15, sbtest20, sbtest30\)..."
mysql -h $DB_HOST -P $DB_PORT -u $DB_USER -p$DB_PASS $DB_NAME << SQL 2>/dev/null
CREATE TABLE IF NOT EXISTS sbtest1 \(id INT\);
CREATE TABLE IF NOT EXISTS sbtest5 \(id INT\);
CREATE TABLE IF NOT EXISTS sbtest10 \(id INT\);
CREATE TABLE IF NOT EXISTS sbtest15 \(id INT\);
CREATE TABLE IF NOT EXISTS sbtest20 \(id INT\);
CREATE TABLE IF NOT EXISTS sbtest30 \(id INT\);
SELECT COUNT\(*\) as table_count FROM information_schema.tables 
WHERE table_schema = '$DB_NAME' AND table_name LIKE 'sbtest%';
SQL

echo ""
echo "Step 2: Testing MySQL cleanup SQL \(new implementation\)..."
mysql -h $DB_HOST -P $DB_PORT -u $DB_USER -p$DB_PASS $DB_NAME << SQL 2>/dev/null
SET @tables = NULL;
SELECT GROUP_CONCAT\(table_schema, '.', table_name\) INTO @tables 
FROM information_schema.tables 
WHERE table_schema = '$DB_NAME' AND table_name LIKE 'sbtest%';
SELECT @tables as tables_to_drop;
SET @dropStmt = IF\(@tables IS NOT NULL, CONCAT\('DROP TABLE IF EXISTS ', @tables\), 'SELECT 1'\);
PREPARE stmt FROM @dropStmt;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;
SQL

echo ""
echo "Step 3: Verifying all sbtest tables are gone..."
mysql -h $DB_HOST -P $DB_PORT -u $DB_USER -p$DB_PASS $DB_NAME << SQL 2>/dev/null
SELECT COUNT\(*\) as remaining_sbtest_tables FROM information_schema.tables 
WHERE table_schema = '$DB_NAME' AND table_name LIKE 'sbtest%';
SQL

echo ""
echo "========================================"
echo "Test Complete"
echo "========================================"
EOF
